  "d": "Tang sarayı Wang Jian’ı Shu Kralı (蜀王) yaptı; Chengdu merkezli Sichuan Tang’ın son yıllarında fiilen bağımsızdı.",
  "kaynak": "Xin Wudai shi, juan 63 (okundu): «三年八月，唐封建蜀王。»",
