  "kaynak": "Xin Wudai shi, juan 68 «Min shijia» (zh.wikisource.org/wiki/新五代史/卷68; açıldı, okundu): «唐亡，梁太祖加拜審知中書令，封閩王，升福州為大都督府。»",
