  "d": "Zheng Renmin’in ardından oğlu Zheng Longtan (Gonghui Di) 926’da tahta çıktı ve 927’de \"Tianying\" dönem adını kullandı; hanedan 927’de yıkıldı.",
  "kaynak": "Theobald, chinaknowledge.de «Nanzhao» (okundu), tablo: «Zheng Longtan 鄭隆亶 (Emperor Gonghui 恭惠帝) (r. 926-927) Tianying 天應 (927)»",
