  "d": "Sinmun 4. yılda Anseung'un yeğeni general Daemun Geumma-jeo'da isyan edince ayaklanma bastırıldı, halkı Silla'nın güneyine sürüldü ve toprağı Geumma-gun yapıldı; Bodeok'un ayrı varlığı bitti.",
  "kaynak": "Kim Busik, Samguk sagi 卷08 (zh.wikisource.org/wiki/三國史記/卷08, okundu): «十一月，安勝族子將軍大文，在金馬渚謀叛，事發伏誅。餘人見大文誅死，殺害官吏，據邑叛，王命將士討之，逆鬪，幢主逼實死之。陷其城，徙其人於國南州郡，以其地爲金馬郡。»",
