  "d": "Baoying 1. yılda Tang imparatoru Balhae komutanlığını krallığa yükseltti ve Dae Hum-mu'yu kral tanıyıp 'kıdemli yardımcı büyük general' unvanını verdi; Balhae başkenti bu sırada (755 sonrası) Sanggyeong'a taşınmıştı.",
  "kaynak": "Xin Tangshu 卷219 (zh.wikisource.org/wiki/新唐書/卷219, okundu): «寶應元年，詔以渤海爲國，欽茂王之，進檢校太尉。»",
