  "kaynak": "Haneji Chōshū, Ryūkyū-koku Chūzan seikan (1650) — ja.wikisource.org/wiki/琉球國中山世鑑/卷一 (okundu): «南宋嘉熈二年戊戌舜馬順熈御即位»",
