  "d": "313 (925) yılı civarında bölgeyi gezen el-Mes'ûdî, Multan valisi olarak Ebû Leheb Mürebbih b. Esed'i anar; otuz yıl kadar sonra gelen İstahrî şehrin yerli halkla Müslümanların dostça birlikte yaşadığı müreffeh bir şehir olduğunu yazar.",
  "kaynak": "TDV İslâm Ansiklopedisi, «Mültan» maddesi, https://islamansiklopedisi.org.tr/multan (22.10.2026'da okundu), «Mültan»: \"313 (925) yılı civarında bölgeyi gezen Ali b. Hüseyin el-Mes‘ûdî, Vali Ebû Leheb Mürebbih b. Esed’den bahseder\"",
