  "kaynak": "R. C. Majumdar (ed.), The History and Culture of the Indian People, Vol. V: The Struggle for Empire, Bharatiya Vidya Bhavan, Bombay 1957 (archive.org: struggleforempir05bhar, tam metin okundu), «The Somavamsis»: \"Uddyotakesarl Mahabhavagupta IV (c. A.D. 1055-80)\"",
