  "kaynak": "R. C. Majumdar (ed.), The History and Culture of the Indian People, Vol. V: The Struggle for Empire, Bharatiya Vidya Bhavan, Bombay 1957 (archive.org: struggleforempir05bhar, tam metin okundu), «The Kalachuris of Ratanpur»: \"in A.D. 1114, became independent during the latter part of Yasahkarna\"",
