  "taraflar": [
   "varman-vanga"
  ],
  "d": "Harivarman kırk altı yıldan uzun hüküm sürdü ve 12. yüzyılın ilk çeyreğinin sonunda öldü; adı bilinmeyen oğlundan sonra küçük kardeşi Samalavarman tahta çıktı. Samalavarman'ın çağdaşı kulapañjî kayıtlarına göre Bengal'e Vaidika Brahmanlarının atası 1079'da (S. 1001) yerleşti.",
  "kaynak": "R. C. Majumdar (ed.), The History and Culture of the Indian People, Vol. V: The Struggle for Empire, Bharatiya Vidya Bhavan, Bombay 1957 (archive.org: hcip-5-struggle-for-empire-ed.-r.-c.-majumdar_202512, tam metin okundu), «Bengal after the Palas: The Yadavas of Vanga»: \"died at the end of the first quarter of the twelfth century A.D.\"",
