  "d": "Sukapha'nın halefi Suteupha 1281'de öldü, yerine oğlu Subinpha geçti; bu dönemde Ahomlar Kamata Racası ile uzun bir savaş yürüttü.",
  "kaynak": "R. C. Majumdar (ed.), The History and Culture of the Indian People, Vol. V: The Struggle for Empire, Bharatiya Vidya Bhavan, Bombay 1957 (archive.org: hcip-5-struggle-for-empire-ed.-r.-c.-majumdar_202512, tam metin okundu), «III. Assam»: \"Suteupha, who died in A.D. 1281\"",
