  "kaynak": "Casim Avcı, «Maldivler», TDV İslâm Ansiklopedisi, https://islamansiklopedisi.org.tr/maldivler (22.10.2026'da okundu), «Maldivler»: \"981’de (1573) Portekizliler adalardan çıkarıldı ve Muhammed Takurufânu sultan ilân edildi\"",
