  "kaynak": "Zhou shu (Linghu Defen vd., 636) juan 50 «Tujue» (Wikisource 周書/卷50, bu oturumda okundu): «魏廢帝元年正月 … 土門死，子科羅立 … 又破叔子於沃野北木賴山。二年三月，科羅遣使獻馬五萬匹» — https://zh.wikisource.org/wiki/周書/卷50",
