  "kaynak": "Jiu Tang shu juan 3 «Taizong ji xia» (Wikisource 舊唐書/卷3, bu oturumda okundu) (貞觀二十三年): «二十三年春正月辛亥，俘龜茲王訶黎布失畢及其相那利等，獻於社廟。»",
