  "kaynak": "Jiu Tang shu (Liu Xu vd., 945) juan 198 «Xirong» (Wikisource 舊唐書/卷198, bu oturumda okundu): «永徽元年，又以訶黎布失畢為右驍衛大將軍，尋放還蕃，撫其餘眾，依舊為龜茲王，賜物一千段。»",
