  "kaynak": "Gronemeyer, S., 'A Preliminary Ruling Sequence of Coba, Quintana Roo', Wayeb Notes No. 14, 2004, https://www.wayeb.org/notes/wayeb_notes0014.pdf (pdftotext ile okundu) | «The front side opens with the Initial Series date 9.11.0.5.9, 4 Muluk 17 K'ayab (January 31, 653) in blocks A1-B9.»",
