  "kaynak": "«Moundville», Alabama Legacy Moments, Alabama Public Television, Haziran 2017 (alabamalegacy.org/moundville; sayfa okundu): \"Founded around 1120, Moundville was located on the banks of the Black Warrior River 14 miles south of present day Tuscaloosa.\" | «Moundville», Alabama Legacy Moments, Alabama Public Television, Haziran 2017 (alabamalegacy.org/moundville; sayfa okundu): \"the site was occupied for more than three centuries but was abandoned by the early sixteenth century.\"",
