  "kaynak": "Mississippi Department of Archives and History, «Grand Village (Natchez Tribal History Center)», trails.mdah.ms.gov/grandvillage (sayfa okundu): \"Archaeologists have determined that the mounds were built during the Plaquemine Period, beginning around AD 1350\" | Mississippi Department of Archives and History, «Grand Village (Natchez Tribal History Center)», trails.mdah.ms.gov/grandvillage (sayfa okundu): \"Beginning around AD 1680, the site was the principal town and capital of the Natchez chiefdom\"",
