  "d": "Bongers ve ark.'na göre Chincha Krallığı olarak bilinen geniş ölçekli polity, Chincha Vadisi'ni on üçüncü yüzyıldan on beşinci yüzyıla, İnka İmparatorluğu'na düşene kadar denetledi. Altı yüzyıl kaynakları polity'nin Chincha ve Pisco vadilerini kapsadığını ve en az 30.000 erkek vergi mükellefi bulunduğunu söyler.",
  "kaynak": "Bongers J. L. ve ark., «Ancient DNA reveals a family ossuary and long-distance migration on the Pacific coast before the Inca Empire», Nature Communications 17, 4222 (2026), doi:10.1038/s41467-026-72216-y (Europe PMC PMC13197425 okundu): \"A large-scale polity known as the Chincha Kingdom controlled the Chincha Valley from the thirteenth century until the fifteenth century, when it fell to the Inca Empire.\" | Bongers J. L. ve ark., «Ancient DNA reveals a family ossuary and long-distance migration on the Pacific coast before the Inca Empire», Nature Communications 17, 4222 (2026), doi:10.1038/s41467-026-72216-y (Europe PMC PMC13197425 okundu): \"This polity’s territory encompassed the Chincha and Pisco valleys and possibly parts of the Topará and Cañete valleys\"",
