  "ic_not": "ÇELİŞKİ: ms1 künyesi f=1100 (Nigra ve ark. 2014, 'Late Intermediate Period ca. AD 1100-1470'); bu kaynak 13. yüzyıl. La Centinela zinciri 13. yüzyıldan (1201) başlatıldı."
