  "d": "Krettek ve ark.'na göre Herrera dönemi 2800–1200 BP arasıdır; yaklaşık 1200 BP'de Altiplano'da Muisca dönemi denilen kültürel evre başladı ve 16. yüzyıl ortasında İspanyol sömürge rejimine kadar sürdü. Kanıtlar Herrera dönemiyle nüfus sürekliliğine işaret eder; Muisca dönemi nüfus artışı, tarım, ticaret ve siyasi karmaşıklaşma ile nitelenir.",
  "kaynak": "Krettek K. L. ve ark., «A 6000-year-long genomic transect from the Bogotá Altiplano...», Science Advances 11, eads6284 (2025), doi:10.1126/sciadv.ads6284 (Europe PMC PMC12118548 okundu): \"Around 1200 yr B.P., a cultural phase, known as the Muisca period, began on the Altiplano and lasted until the imposition of the Hispanic Colonial regime in the mid-16th century\" | Krettek K. L. ve ark., «A 6000-year-long genomic transect from the Bogotá Altiplano...», Science Advances 11, eads6284 (2025), doi:10.1126/sciadv.ads6284 (Europe PMC PMC12118548 okundu): \"The Muisca period is characterized by a relatively continuous process of demographic growth, development of agriculture and trade, and social and political complexification.\"",
