  "yer": "Puerto Rico",
  "taraflar": [
   "taino-seflikleri"
  ],
  "d": "Rodríguez Ramos ve ark.'nın Bayes modeli, Rouse'un Capá üslubu için önerdiği ca. 1200–1500 sınırını doğrular: en erken modellenmiş başlangıç mcal AD 1200, en geç bitiş mcal AD 1500. Capá ve Esperanza, Chican Ostionoid'in (klasik Taíno çanak geleneği) iki üslubudur; yazarlar üslup değişimini doğrudan toplumsal karmaşıklaşmayla (şeflik) eşitlemenin yeniden düşünülmesi gerektiğini söyler.",
  "kaynak": "Rodríguez Ramos R., Rodríguez López M., Pestle W. J., «Revision of the cultural chronology of precolonial Puerto Rico: A Bayesian approach», PLOS ONE 18, e0282052 (2023), doi:10.1371/journal.pone.0282052 (Europe PMC PMC9946257 tam metin okundu): \"Rouse’s chronology of the Capá style, based on a single date from Caguana, postulated a 300-year-long phase extending from ca. 1200 to 1500 AD. Our modeling confirms this finding, with the earliest modeled boundary start date (mcalAD 1200) and latest modeled boundary end date (mcalAD 1500) aligning exactly with Rouse’s proposed temporal boundaries of the style\" | Rodríguez Ramos R., Rodríguez López M., Pestle W. J., «Revision of the cultural chronology of precolonial Puerto Rico: A Bayesian approach», PLOS ONE 18, e0282052 (2023), doi:10.1371/journal.pone.0282052 (Europe PMC PMC9946257 tam metin okundu): \"At AD 900, in the eastern part of the island the Monserrate style gives way to the Santa Elena style, which by AD 1200 transforms into the Esperanza style of the Chican Ostionoid.\"",
  "gun": "mcal AD 1200–1500 (Capá üslubu; en eski uç yazıldı)",
  "kesinlik": "yuzyil",
  "kaynak_turu": "arkeoloji",
  "aralik": {
   "bas": "1200-01-01",
   "son": "1500-01-01",
   "guven": "95.4",
   "tur": "tipolojik"
  },
  "ic_not_d": "ARALIK→EN ESKİ UÇ: 1200–1500 üslubun süresidir (tipolojik, model %95,4 aralığı); orta nokta ALINMADI, t = 1200-01-01.",
  "ic_not": "ÜSLUP TARİHİ ≠ SİYASÎ BİRİM: bu makale çanak üslubunu tarihler; şeflik (cacicazgo) siyasi yapısını tarihlemez ve yazarlar eşitlemeye karşı çıkar. Esperanza üslubu için model daha geniş (mcal AD 880–1640, n=11) çıkar. Yalnız Porto Riko; Hispaniola/Küba cacicazgo tarihleri bu kaynakta yok. Künye f/t bu yüzden BEYANLI YAKLAŞIKLIKtır."
